// Calculate supplier performance
const orders = $input.all();
const supplierStats = {};

for (const order of orders) {
  const supplier = order.json.partner_id ? order.json.partner_id[1] : 'Unknown';
  const plannedDate = new Date(order.json.date_planned);
  const actualDate = new Date(order.json.date_order);
  const daysDiff = Math.floor((actualDate - plannedDate) / (1000 * 60 * 60 * 24));

  if (!supplierStats[supplier]) {
    supplierStats[supplier] = {
      name: supplier,
      total_orders: 0,
      on_time: 0,
      late_1_2_days: 0,
      late_3_plus: 0,
      avg_delay: 0
    };
  }

  supplierStats[supplier].total_orders++;

  if (daysDiff <= 0) {
    supplierStats[supplier].on_time++;
  } else if (daysDiff <= 2) {
    supplierStats[supplier].late_1_2_days++;
  } else {
    supplierStats[supplier].late_3_plus++;
  }
}

// Calculate scores
const result = Object.values(supplierStats).map(s => {
  const score = ((s.on_time * 10) + (s.late_1_2_days * 5) - (s.late_3_plus * 5)) / Math.max(s.total_orders, 1);
  return {
    ...s,
    score: Math.round(score * 10) / 10,
    on_time_rate: Math.round((s.on_time / s.total_orders) * 100)
  };
}).sort((a, b) => b.score - a.score);

return [{ json: { suppliers: result } }];

// Format report
const data = $input.first().json;
const topPerformers = data.suppliers.filter(s => s.score >= 8);
const needsImprovement = data.suppliers.filter(s => s.score < 6);

let message = '📊 SUPPLIER PERFORMANCE REPORT\n\n';
message += '🏆 Top Performers:\n';
if (topPerformers.length > 0) {
  topPerformers.slice(0, 3).forEach(s => {
    message += `• ${s.name}: ${s.score}/10 (${s.on_time_rate}% on-time)\n`;
  });
} else {
  message += '• None this week\n';
}

message += '\n⚠️ Needs Improvement:\n';
if (needsImprovement.length > 0) {
  needsImprovement.forEach(s => {
    message += `• ${s.name}: ${s.score}/10 (${s.late_3_plus} late deliveries)\n`;
  });
} else {
  message += '• None this week\n';
}

return [{ json: { report: message, top: topPerformers, improvement: needsImprovement } }];
